/// `Supervisor::spawn`/`restart` so a restart can replace the process/client/reader
/// triple without losing the restart-attempt bookkeeping a fresh `Supervisor` would
/// otherwise reset.
async fn spawn_process(
    config: &SupervisorConfig,
) -> Result<(Child, Client, tokio::task::JoinHandle<TscClientError>), TscClientError> {
    check_version(&config.tsc_path, config.expected_versions)?;

    let mut command = Command::new(config.tsc_path.as_std_path());
    command.arg("--api").arg("--async").arg("--cwd").arg(config.cwd.as_std_path());
